# Find the sex column (case-insensitive check)
sex_col = None
for col in df.columns:
    if col.lower().strip() == 'sex':
        sex_col = col
        break

if sex_col:
    df[sex_col] = df[sex_col].map({"male" : 0,"female" : 1})
else:
    print("Warning: 'sex' column not found in dataframe")
